from itertools import combinations, permutations
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

def solve_bip(a,b, minedges=23):
    var={}
    v=1
    for i in range(a):
        for j in range(b):
            var[(i,j)]=v; v+=1
    clauses=[]
    # no C4: for two rows, two cols not all present
    for r1,r2 in combinations(range(a),2):
        for c1,c2 in combinations(range(b),2):
            clauses.append([-var[(r1,c1)],-var[(r1,c2)],-var[(r2,c1)],-var[(r2,c2)]])
    # no C6: cycle using 3 rows and 3 cols. Need all six cross edge pattern r0-c0,r0-c2,r1-c0,r1-c1,r2-c1,r2-c2 for permutations columns assigned intersections.
    cyc=0
    for rows in combinations(range(a),3):
        r0,r1,r2=rows
        for cols in combinations(range(b),3):
            for perm in permutations(cols):
                c01,c12,c20=perm  # intersections rows (r0,r1), (r1,r2), (r2,r0)
                lits=[var[(r0,c01)],var[(r1,c01)],var[(r1,c12)],var[(r2,c12)],var[(r2,c20)],var[(r0,c20)]]
                clauses.append([-x for x in lits]); cyc+=1
    lits=[var[(i,j)] for i in range(a) for j in range(b)]
    cnf=CardEnc.atleast(lits=lits,bound=minedges,top_id=v-1,encoding=EncType.seqcounter)
    clauses.extend(cnf.clauses)
    with Glucose3(bootstrap_with=clauses) as s:
        sat=s.solve()
        if sat:
            m=set(s.get_model())
            edges=[]
            for i in range(a):
                for j in range(b):
                    if var[(i,j)] in m:
                        edges.append((i,a+j))
            return edges
    return None
for a in range(1,16):
    b=16-a
    if a*b<23: continue
    print('trying',a,b)
    sol=solve_bip(a,b,23)
    print(' result', None if sol is None else len(sol))
    if sol:
        print(sol)
        break

import random, collections, itertools, time
n=16
all_edges=[(i,j) for i in range(n) for j in range(i+1,n)]

def dist(adj,s,t):
    if s==t: return 0
    seen={s}; q=collections.deque([(s,0)])
    while q:
        v,d=q.popleft()
        if d>=6: continue
        for w in adj[v]:
            if w==t: return d+1
            if w not in seen:
                seen.add(w); q.append((w,d+1))
    return 99

def colorable(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    order=sorted(range(n), key=lambda x:-len(adj[x]))
    col=[-1]*n
    def bt(k):
        if k==n: return True
        v=order[k]
        forb={col[w] for w in adj[v] if col[w]>=0}
        for c in range(3):
            if c not in forb:
                col[v]=c
                if bt(k+1): return True
                col[v]=-1
        return False
    return bt(0)

def greedy():
    adj=[set() for _ in range(n)]; edges=[]
    candidates=all_edges[:]
    while True:
        legal=[]
        for u,v in candidates:
            if v in adj[u]: continue
            if dist(adj,u,v)>=6:
                legal.append((u,v))
        if not legal: return edges
        # random shuffle candidates score? choose edge that leaves many legal maybe
        random.shuffle(legal)
        added=False
        for e in legal[:]:
            newedges=edges+[e]
            if colorable(newedges):
                u,v=e; adj[u].add(v); adj[v].add(u); edges.append(e); added=True; break
        if not added: return edges

